/* --- 末世科技风格（暗色系红色点缀）--- */

/* 1. 全局包裹层：高科技废土 */
.survival-interface {
    background: linear-gradient(135deg, #1a1d23 0%, #0f1115 100%);
    border-radius: 16px;
    padding: 24px;
    box-shadow: 
        0 20px 60px rgba(0, 0, 0, 0.5),
        0 0 0 1px rgba(239, 68, 68, 0.05) inset;
    position: relative;
    color: #c4c4c4;
    font-family: 'Segoe UI', 'Roboto', 'Microsoft YaHei', sans-serif;
    line-height: 1.7;
    max-width: 900px;
    margin: 0 auto;
    overflow: hidden;
}

/* 顶部光晕效果 */
.survival-interface::after {
    content: '';
    position: absolute;
    top: -50%; left: -50%;
    width: 200%; height: 200%;
    background: radial-gradient(circle at 20% 20%, rgba(239, 68, 68, 0.08) 0%, transparent 50%);
    pointer-events: none;
}

/* --- 1. 时间轴：现代终端风格 --- */
code.language-Time {
    display: block;
    background: linear-gradient(135deg, #0a0c10 0%, #13151a 100%);
    border: 1px solid rgba(239, 68, 68, 0.2);
    border-left: 4px solid #dc2626;
    padding: 16px 24px;
    color: #fca5a5;
    font-family: 'JetBrains Mono', 'Fira Code', monospace;
    margin-bottom: 24px;
    white-space: pre-wrap;
    box-shadow: 
        0 4px 20px rgba(0, 0, 0, 0.3),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);
    position: relative;
    border-radius: 8px;
}

/* --- 2. 折叠栏：玻璃卡片风格 --- */
details {
    border-radius: 12px;
    overflow: hidden;
    background: transparent;
    border: none;
    margin-bottom: 12px;
    transition: all 0.3s ease;
}

details[open] {
    /* 打开时不需要额外样式 */
}

summary {
    display: flex;
    align-items: center;
    padding: 16px 24px;
    font-weight: 600;
    color: #e0e0e0;
    background: rgba(26, 29, 35, 0.8);
    cursor: pointer;
    list-style: none;
    text-transform: uppercase;
    letter-spacing: 1px;
    transition: all 0.3s ease;
    position: relative;
    font-size: 14px;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    backdrop-filter: blur(10px);
}

summary:hover {
    background: rgba(40, 44, 52, 0.9);
    color: #fff;
    border-color: rgba(239, 68, 68, 0.3);
}

/* 发光指示器 */
summary::before {
    content: '▸';
    margin-right: 12px;
    color: #dc2626;
    font-size: 12px;
    transition: transform 0.3s ease;
}

details[open] > summary::before {
    transform: rotate(90deg);
    color: #fca5a5;
}

/* 状态标签 */
summary::after {
    content: 'OFFLINE';
    font-size: 10px;
    position: absolute;
    right: 24px;
    padding: 4px 10px;
    border-radius: 20px;
    background: rgba(239, 68, 68, 0.2);
    color: #ef4444;
    font-weight: 500;
    transition: all 0.3s ease;
}

details[open] > summary::after {
    content: 'ONLINE';
    background: rgba(220, 38, 38, 0.2);
    color: #dc2626;
}

/* 🎯 折叠内容区：独立的深色卡片风格 */
details > *:not(summary) {
    background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
    margin-top: 8px;
    padding: 20px 24px;
    color: #c4c4c4;
    line-height: 1.7;
    font-size: 15px;
    position: relative;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    box-shadow: 
        0 4px 20px rgba(0, 0, 0, 0.3),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

/* --- 3. 警告与威胁：现代化徽章 --- */
.threat-level {
    background: linear-gradient(135deg, rgba(239, 68, 68, 0.15) 0%, rgba(239, 68, 68, 0.05) 100%);
    color: #ef4444;
    padding: 6px 14px;
    font-weight: 600;
    border-radius: 20px;
    font-size: 12px;
    border: 1px solid rgba(239, 68, 68, 0.3);
    text-transform: uppercase;
    letter-spacing: 1px;
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

.threat-level::before {
    content: '⚠';
    font-size: 10px;
}

.threat-level.low {
    background: linear-gradient(135deg, rgba(245, 158, 11, 0.15) 0%, rgba(245, 158, 11, 0.05) 100%);
    color: #f59e0b;
    border-color: rgba(245, 158, 11, 0.3);
}

.threat-level.low::before {
    content: '⚡';
}

.threat-level.medium {
    background: linear-gradient(135deg, rgba(249, 115, 22, 0.15) 0%, rgba(249, 115, 22, 0.05) 100%);
    color: #f97316;
    border-color: rgba(249, 115, 22, 0.3);
}

.threat-level.medium::before {
    content: '◆';
}

.threat-level.high {
    background: linear-gradient(135deg, rgba(220, 38, 38, 0.2) 0%, rgba(220, 38, 38, 0.08) 100%);
    color: #dc2626;
    border-color: rgba(220, 38, 38, 0.5);
    animation: threat-pulse 2s ease-in-out infinite;
}

.threat-level.high::before {
    content: '⚠';
}

@keyframes threat-pulse {
    0%, 100% { 
        box-shadow: 0 0 0 0 rgba(220, 38, 38, 0.4);
    }
    50% { 
        box-shadow: 0 0 0 8px rgba(220, 38, 38, 0);
    }
}

/* --- 4. 记忆栏与档案：数据卡片风格 --- */
.memory-zone {
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(26, 29, 35, 0.4);
    padding: 0;
    border-radius: 12px;
    margin-top: 16px;
    overflow: hidden;
    backdrop-filter: blur(10px);
}

/* 档案标题 */
.memory-zone-header {
    display: block;
    background: linear-gradient(135deg, #dc2626 0%, #b91c1c 100%);
    color: #fff;
    padding: 14px 24px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 2px;
    font-size: 12px;
    position: relative;
}

.memory-zone-header::before {
    content: '📊';
    margin-right: 8px;
}

.memory-item {
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    padding: 14px 24px;
    position: relative;
    transition: all 0.3s ease;
    color: #c4c4c4;
}

.memory-item::before {
    content: '';
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    width: 4px;
    height: 4px;
    background: #dc2626;
    border-radius: 50%;
    box-shadow: 0 0 8px rgba(220, 38, 38, 0.5);
}

.memory-item:hover {
    background: rgba(220, 38, 38, 0.05);
    padding-left: 32px;
}

.memory-item:last-child {
    border-bottom: none;
}

/* --- 5. 分割线：现代分割线 --- */
hr {
    border: 0;
    height: 1px;
    background: linear-gradient(to right, transparent, rgba(239, 68, 68, 0.1), transparent);
    margin: 32px 0;
    position: relative;
}

/* --- 6. 强调文本：高亮标记 --- */
strong {
    color: #fca5a5;
    background: rgba(239, 68, 68, 0.1);
    padding: 2px 8px;
    border-radius: 4px;
    font-weight: 600;
}

/* --- 7. 状态块和选项块：代码编辑器风格 --- */
.status-block, .options-block {
    background: linear-gradient(135deg, #0f1115 0%, #1a1d23 100%);
    border-radius: 12px;
    padding: 20px 24px;
    font-family: 'JetBrains Mono', 'Fira Code', monospace;
    font-size: 14px;
    line-height: 1.8;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-left: 4px solid #dc2626;
    white-space: pre-wrap;
    word-break: break-word;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
    color: #c4c4c4;
    position: relative;
}

/* 行号装饰 */
.status-block::before,
.options-block::before {
    content: '';
    position: absolute;
    top: 0; left: 0; width: 4px; height: 100%;
    background: linear-gradient(180deg, #dc2626 0%, #b91c1c 100%);
}

/* --- 8. 响应式调整 --- */
@media (max-width: 768px) {
    .survival-interface {
        padding: 16px;
        border-radius: 12px;
    }

    summary {
        padding: 14px 20px;
        font-size: 13px;
    }

    summary::after {
        right: 20px;
        font-size: 9px;
    }

    .memory-zone-header {
        font-size: 11px;
        padding: 12px 20px;
    }

    .memory-item {
        padding: 12px 20px;
        font-size: 14px;
    }

    .status-block, .options-block {
        padding: 16px 20px;
        font-size: 13px;
    }

    details > *:not(summary) {
        padding: 16px 20px;
        font-size: 14px;
    }
}

/* --- 9. 对话颜色规范（现代风格）--- */
/* 玩家言语（暗红色） */
font[color="#00c6c6"],
.dialog-player {
    color: #ef4444 !important;
    font-weight: 600;
    background: rgba(239, 68, 68, 0.1);
    padding: 2px 8px;
    border-radius: 4px;
}

/* 女性NPC言语（粉紫色） */
font[color="#FF2D2D"],
.dialog-female {
    color: #fca5a5 !important;
    font-style: italic;
    background: rgba(252, 165, 165, 0.1);
    padding: 2px 8px;
    border-radius: 4px;
}

/* 男性NPC言语（橙红色） */
font[color="#ea0029"],
.dialog-male {
    color: #f97316 !important;
    font-weight: 600;
    background: rgba(249, 115, 22, 0.1);
    padding: 2px 8px;
    border-radius: 4px;
}

/* --- 10. 实用工具类 --- */
.glow-indigo {
    color: #dc2626;
    text-shadow: 0 0 20px rgba(220, 38, 38, 0.5);
}

.border-glass {
    border: 1px solid rgba(255, 255, 255, 0.1);
    backdrop-filter: blur(10px);
}

.bg-dark-tech {
    background: linear-gradient(135deg, #1a1d23 0%, #0f1115 100%);
}

.text-gradient {
    background: linear-gradient(135deg, #dc2626 0%, #ef4444 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.card-hover {
    transition: all 0.3s ease;
}

.card-hover:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}
